// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkAction) predicate.WorkAction {
	return predicate.WorkAction(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkAction) predicate.WorkAction {
	return predicate.WorkAction(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkAction) predicate.WorkAction {
	return predicate.WorkAction(sql.NotPredicates(p))
}
